// Verus program: chebweight
// Given a non-empty input vector `x`, produce a vector of the same length `n`
// where endpoints get weight 0.5 and all interior indices get weight 1.0.

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: int|
            0 <= i < result.len() ==> (
                if i == 0 || i == (result.len() as int) - 1 {
                    result[i] == 0.5f32
                } else {
                    result[i] == 1.0f32
                }
            ),
{
    let n: usize = x.len();

    // Build output vector with the required weights.
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            n == x.len(),
            result.len() == i,
            i <= n,
            forall|j: int|
                0 <= j < i as int ==> (
                    if j == 0 || j == (n as int) - 1 {
                        result[j] == 0.5f32
                    } else {
                        result[j] == 1.0f32
                    }
                ),
    {
        let w: f32 = if i == 0 || i + 1 == n { 0.5f32 } else { 1.0f32 };
        result.push(w);
        i += 1;
    }

    result
}

} // verus!